UNITS = {
    "cero": 0, "dos": 2, "tres": 3, "cuatro": 4, "cinco": 5, "seis": 6, "siete": 7,
    "ocho": 8, "nueve": 9, "diez": 10, "once": 11, "doce": 12, "trece": 13,
    "catorce": 14, "quince": 15, "dieciseis": 16, "diecisiete": 17, "dieciocho": 18,
    "diecinueve": 19, "veinte": 20, "veintiuno": 21, "veintiun": 21, "veintidos": 22,
    "veintitres": 23, "veinticuatro": 24, "veinticinco": 25, "veintiseis": 26,
    "veintisiete": 27, "veintiocho": 28, "veintinueve": 29, "treinta": 30,
    "cuarenta": 40, "cincuenta": 50, "sesenta": 60, "setenta": 70, "ochenta": 80,
    "noventa": 90, "cien": 100, "ciento": 100, "doscientos": 200, "doscientas": 200,
    "trescientos": 300, "trescientas": 300, "cuatrocientos": 400, "cuatrocientas": 400,
    "quinientos": 500, "quinientas": 500, "seiscientos": 600, "seiscientas": 600,
    "setecientos": 700, "setecientas": 700, "ochocientos": 800, "ochocientas": 800,
    "novecientos": 900, "novecientas": 900,
}
MULTS = {"mil": 1000, "millon": 1e6, "millones": 1e6}
# palabras que expresan una relación numérica: no son una cifra «nueva»
REL = {"doble": 2, "triple": 3, "mitad": 0.5, "cuadruple": 4}

TIME_RE = re.compile(r"\b(\d{1,2})[:h](\d{2})\b")
NUM_RE = re.compile(r"\d+(?:[. ]\d{3})*(?:,\d+)?|\d+(?:\.\d+)?")


def _parse_digit(tok):
    if re.fullmatch(r"\d{1,3}(?:[. ]\d{3})+", tok):
        return float(tok.replace(".", "").replace(" ", ""))
    if "," in tok:
        return float(tok.replace(".", "").replace(",", "."))
    try:
        return float(tok)
    except ValueError:
        return None


def extract_numbers(text):
    """Devuelve lista de valores numéricos (cifras y números en letra)."""
    t = norm(text)
    vals = []
    # las horas (10:05) se tratan como minutos del día, no como dos cifras
    for h, mi in TIME_RE.findall(t):
        if int(h) < 24 and int(mi) < 60:
            vals.append(-(1 + int(h) * 60 + int(mi)))  # horas: valor negativo (marca)
    t = TIME_RE.sub(" ", t)
    for m in NUM_RE.finditer(t):
        v = _parse_digit(m.group(0))
        if v is None:
            continue
        vals.append(v)
        tail = t[m.end():m.end() + 10]
        if re.match(r"\s*(millon|millones)", tail):
            vals.append(v * 1e6)
        elif re.match(r"\s*mil\b", tail):
            vals.append(v * 1000)
    # números escritos en letra (con «y» y multiplicadores)
    words = WORD_RE.findall(t)
    i = 0
    while i < len(words):
        w = words[i]
        if w in UNITS or (w == "mil" and (i == 0 or words[i - 1] not in UNITS)):
            total, cur, j = 0.0, 0.0, i
            while j < len(words):
                x = words[j]
                if x in UNITS:
                    cur += UNITS[x]
                elif x == "mil":
                    total += (cur or 1) * 1000
                    cur = 0
                elif x in ("millon", "millones"):
                    total += (cur or 1) * 1e6
                    cur = 0
                elif x == "y" and j + 1 < len(words) and words[j + 1] in UNITS:
                    pass
                else:
                    break
                j += 1
            vals.append(total + cur)
            i = j
        else:
            i += 1
    # «cuatro de cada diez» -> 40 % (y se retiran el 4 y el 10 sueltos)
    for m in re.finditer(r"(\w+) de cada (\w+)", t):
        a = _word_or_digit(m.group(1))
        b = _word_or_digit(m.group(2))
        if a and b:
            for x in (a, b):
                if x in vals:
                    vals.remove(x)
            vals.append(100.0 * a / b)
    return vals


def _word_or_digit(w):
    if w in UNITS:
        return UNITS[w]
    if w == "cien":
        return 100
    if w == "mil":
        return 1000
    try:
        return float(w)
    except ValueError:
        return None


def close(a, b):
    if a == b:
        return True
    m = max(abs(a), abs(b))
    return m > 0 and abs(a - b) <= 0.006 * m


def derived_values(nums):
    """Cuentas exactas permitidas por el criterio: sumas, restas, productos,
    porcentajes, doble/mitad..."""
    base = sorted(set(v for v in nums if v > 0))[:80]
    out = set(base)
    for a in base:
        for k in (2, 3, 4, 0.5, 100, 0.01, 1000, 0.001, 12, 1 / 12):
            out.add(a * k)
    for i, a in enumerate(base):
        for b in base[i + 1:]:
            out.update((a + b, abs(a - b), a * b))
            if a:
                out.update((b / a, 100 * b / a, a * b / 100, 100 * (b - a) / a))
            if b:
                out.update((a / b, 100 * a / b, 100 * (b - a) / b))
    for a in base:  # sumas de tres (repartos «el resto»)
        pass
    for i, a in enumerate(base):
        out.add(100 - a)
        for b in base[i + 1:]:
            out.add(100 - a - b)
    return sorted(out)


def extract_times(text):
    return [int(h) * 60 + int(m) for h, m in TIME_RE.findall(norm(text)) if int(h) < 24 and int(m) < 60]


def tight_derived(ans_nums, src_nums, times=()):
    """Cuentas en las que al menos un operando aparece en la propia oración:
    es lo que hace una respuesta fiel («86 quesos, 14 más que los 72 de 2025»)."""
    out = set()
    src = sorted(set(src_nums))[:60]
    for a in set(ans_nums):
        for b in src:
            out.update((a + b, abs(a - b), a * b))
            if b:
                out.update((a / b, 100 * a / b, 100 * (a - b) / b, a * b / 100))
            if a:
                out.update((b / a, 100 * b / a, 100 * (b - a) / a))
        for k in (2, 3, 4, 0.5, 100, 0.01, 12):
            out.add(a * k)
        out.add(100 - a)
    tl = list(times)
    for i, a in enumerate(tl):
        for b in tl[i + 1:]:
            out.add(abs(a - b))
    return out


PCT_RE = re.compile(r"(\d+(?:,\d+)?)\s*(?:%|por ciento)")


def extract_pcts(text):
    t = norm(text)
    out = [float(m.group(1).replace(",", ".")) for m in PCT_RE.finditer(t)]
    for m in re.finditer(r"(\w+) de cada (\w+)", t):
        a, b = _word_or_digit(m.group(1)), _word_or_digit(m.group(2))
        if a and b:
            out.append(100.0 * a / b)
    for w, v in (("la mitad", 50.0), ("un tercio", 100 / 3), ("un cuarto", 25.0),
                 ("dos tercios", 200 / 3), ("tres cuartas", 75.0)):
        if w in t:
            out.append(v)
    return out


def is_year(v):
    return 1900 <= v <= 2100 and float(v).is_integer()


def internal_derived(nums, times=()):
    """Cuentas hechas SOLO con las cifras de la propia oración."""
    out = set()
    ns = list(nums)
    for i, a in enumerate(ns):
        out.update((100 - a, a * 2, a / 2, a * 100, a / 100, a * 12, a / 12))
        for j, b in enumerate(ns):
            if i == j:
                continue
            out.update((a + b, a - b, a * b, a * b / 100, 100 - a - b, (a - b) * 100, (a - b) / 100))
            for c in ns:
                if c is not a and c is not b:
                    out.add(a - b - c)
            if b:
                out.update((a / b, 100 * a / b, 100 * (a - b) / b))
    tl = list(times)
    for i, a in enumerate(tl):
        for b in tl[i + 1:]:
            out.add(abs(a - b))
    return sorted({abs(x) for x in out})


def limited_cross(nums, src_nums):
    """Una cifra de la oración combinada con una de las fuentes (sumas, restas y
    porcentajes): «61.300 tapas, 6.500 más que en 2025»."""
    out = set()
    src = sorted(set(src_nums))[:40]
    for a in nums:
        for i, b in enumerate(src):
            out.update((a + b, abs(a - b), a * b / 100))
            for c in src[i + 1:]:
                out.add(a - b - c)  # «el resto»
            if b:
                out.add(100 * a / b)
            if a:
                out.add(100 * b / a)
    return sorted(out)


def num_match(v, pool):
    """¿v coincide (tolerancia relativa 0,6 %) con algún valor del conjunto?
    Las listas se asumen ordenadas (búsqueda binaria: rápido con miles de cuentas)."""
    if isinstance(pool, list):
        tol = 0.0061 * abs(v)
        i = bisect.bisect_left(pool, v - tol)
        while i < len(pool) and pool[i] <= v + tol:
            if close(v, pool[i]):
                return True
            i += 1
        return False
    return any(close(v, p) for p in pool)


def is_trivial(v):
    return v in (0, 1)


